{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    # Validate fields
    for n in nodes:
        if n not in core:
            raise ValueError(f"Missing core distance for {n}")
    # Build distance lookup
    dist_dict = {}
    for a, b, d in distances:
        if a < b:
            dist_dict[(a, b)] = d
        else:
            dist_dict[(b, a)] = d
    # Prepare edges with mutual reachability
    edges = []
    n = len(nodes)
    for i in range(n):
        for j in range(i+1, n):
            a, b = nodes[i], nodes[j]
            d = dist_dict.get((a, b))
            if d is None:
                raise ValueError(f"Missing distance between {a} and {b}")
            w = max(core[a], core[b], d)
            edges.append((w, a, b))
    # Sort: primary weight, secondary canonized endpoints
    edges.sort(key=lambda e: (e[0], e[1], e[2]))
    # Union-Find
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        xr, yr = find(x), find(y)
        if xr == yr:
            return False
        if rank[xr] < rank[yr]:
            parent[xr] = yr
        elif rank[xr] > rank[yr]:
            parent[yr] = xr
        else:
            parent[yr] = xr
            rank[xr] += 1
        return True
    # Kruskal
    mst = []
    total = 0.0
    for w, a, b in edges:
        if len(mst) == n - 1:
            break
        if union(a, b):
            mst.append([a, b, w])
            total += w
    if len(mst) != n - 1:
        raise ValueError("Graph is disconnected")
    return {'mst_edges': mst, 'total_weight': total}"
}
